    x = pos.get("x", 0) if isinstance(pos, dict) else 0
    y = pos.get("y", 0) if isinstance(pos, dict) else 0

    # If there are resources or rivals, try to move toward/away safely.
    # Prefer staying in place if unknowns.
    dx = 0
    dy = 0

