    # Build simple heuristics from common fields defensively.
    # toward nearest resource
    resources = observation.get("resources", [])
    if isinstance(resources, list) and resources:
        # pick closest resource
        best = None
        for r in resources:
            rx = r.get("x", 0)
            ry = r.get("y", 0)
            dist = abs(rx - x) + abs(ry - y)
            if best is None or dist < best[0]:
                best = (dist, rx, ry)
        if best:
            rx, ry = best[1], best[2]
            if rx > x:
                dx = 1
            elif rx < x:
                dx = -1
            if ry > y:
                dy = 1
            elif ry < y:
                dy = -1

    # If no resource or already moved, try simple exploration: stay near center
